import React, { useEffect, useMemo, useState } from 'react';
import { useLocation, useNavigate } from 'react-router-dom';
import axios from 'axios';
import Sidebar from '../components/Sidebar';
import PasswordInput from '../components/PasswordInput';
import '../css/Dashboard.css';
import '../css/Users.css';
import { API_BASE_URL } from '../constants/api';

const ROLE_LABELS = {
  FM: 'FM - Facilities Manager',
  Tenant: 'Tenant - Unit Owner',
  Staff: 'Staff - Worker'
};

const emptyFilters = {
  query: '',
  role: 'All',
  status: 'All',
  faceId: 'All'
};

const Users = () => {
  const navigate = useNavigate();
  const location = useLocation();
  const [users, setUsers] = useState([]);
  const [loading, setLoading] = useState(true);
  const [modal, setModal] = useState({ isOpen: false, user: null, action: null });
  const [confirmText, setConfirmText] = useState('');
  const [modalError, setModalError] = useState('');
  const [notification, setNotification] = useState(location.state?.notice || '');
  const [filters, setFilters] = useState(emptyFilters);

  const token = localStorage.getItem('accessToken');
  const currentUserId = localStorage.getItem('userId');
  const role = localStorage.getItem('userRole');

  const [addOpen, setAddOpen] = useState(false);
  const [newUser, setNewUser] = useState({ name: '', email: '', password: '' });
  const [addSubmitting, setAddSubmitting] = useState(false);
  const [addError, setAddError] = useState('');

  const fetchUsers = async () => {
    setLoading(true);
    try {
      const response = await axios.get(`${API_BASE_URL}/user`, {
        headers: { Authorization: `Bearer ${token}` }
      });
      setUsers(Array.isArray(response.data) ? response.data : []);
    } catch (error) {
      console.error('Database sync failed:', error);
      setUsers([]);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchUsers();
  }, []);

  useEffect(() => {
    if (!notification) return undefined;
    const timer = setTimeout(() => setNotification(''), 4000);
    return () => clearTimeout(timer);
  }, [notification]);

  const summary = useMemo(() => ({
    total: users.length,
    active: users.filter((u) => u.isActive !== false).length,
    suspended: users.filter((u) => u.isActive === false).length,
    enrolled: users.filter((u) => Boolean(u.isEnrolled)).length
  }), [users]);

  const filteredUsers = useMemo(() => users.filter((user) => {
    const query = filters.query.trim().toLowerCase();
    const matchesQuery = !query
      || user.name?.toLowerCase().includes(query)
      || user.email?.toLowerCase().includes(query);
    const matchesRole = filters.role === 'All' || user.role === filters.role;
    const matchesStatus = filters.status === 'All'
      || (filters.status === 'Active' ? user.isActive !== false : user.isActive === false);
    const matchesFaceId = filters.faceId === 'All'
      || (filters.faceId === 'Enrolled' ? Boolean(user.isEnrolled) : !user.isEnrolled);
    return matchesQuery && matchesRole && matchesStatus && matchesFaceId;
  }), [users, filters]);

  const onNewField = (e) => setNewUser((prev) => ({ ...prev, [e.target.name]: e.target.value }));
  const onFilterChange = (e) => setFilters((prev) => ({ ...prev, [e.target.name]: e.target.value }));

  const openAdd = () => {
    setAddError('');
    setNewUser({ name: '', email: '', password: '' });
    setAddOpen(true);
  };
  const closeAdd = () => setAddOpen(false);

  const createTenant = async (e) => {
    e.preventDefault();
    setAddSubmitting(true);
    setAddError('');
    try {
      await axios.post(`${API_BASE_URL}/user/manual-create`, newUser, { headers: { Authorization: `Bearer ${token}` } });
      setAddOpen(false);
      setNotification(`Tenant account created for ${newUser.name}.`);
      fetchUsers();
    } catch (err) {
      setAddError(err.response?.data?.errors?.[0] || err.response?.data?.message || 'Failed to create account.');
    } finally {
      setAddSubmitting(false);
    }
  };

  const openModal = (user, action = 'suspend') => {
    setConfirmText('');
    setModalError('');
    setModal({ isOpen: true, user, action });
  };

  const closeModal = () => {
    setModal({ isOpen: false, user: null, action: null });
    setConfirmText('');
    setModalError('');
  };

  const handleConfirmAction = async () => {
    const { id, isActive, name } = modal.user;
    setModalError('');

    if (modal.action === 'delete' && confirmText !== name) {
      setModalError(`Type ${name} to confirm permanent off-boarding.`);
      return;
    }

    try {
      if (modal.action === 'delete') {
        await axios.delete(`${API_BASE_URL}/user/${id}`, {
          headers: { Authorization: `Bearer ${token}` }
        });
        await fetchUsers();
        setNotification(`${name} was permanently removed from FlowGuard.`);
        closeModal();
        return;
      }

      await axios.put(`${API_BASE_URL}/user/suspend/${id}`, {}, {
        headers: { Authorization: `Bearer ${token}` }
      });
      setUsers((prevUsers) => prevUsers.map((u) => (u.id === id ? { ...u, isActive: !isActive } : u)));
      closeModal();
    } catch (error) {
      setModalError(error.response?.data?.message || error.response?.data?.error || `Failed to ${modal.action === 'delete' ? 'remove' : 'update access for'} ${name}.`);
      console.error(error);
    }
  };

  const renderRoleBadge = (userRole) => (
    <span className={`role-badge role-${String(userRole).toLowerCase()}`} aria-label={`Role: ${ROLE_LABELS[userRole] || userRole}`}>
      {ROLE_LABELS[userRole] || userRole}
    </span>
  );

  const renderStatusBadge = (user) => (
    <span className={`account-status-badge ${user.isActive === false ? 'suspended' : 'active'}`} role="status">
      {user.isActive === false ? 'Suspended' : 'Active'}
    </span>
  );

  return (
    <div className="dashboard-layout">
      <Sidebar />

      <main className="dashboard-main">
        {modal.isOpen && (
          <div className="modal-overlay">
            <div className={`modal-content security-modal ${modal.action === 'delete' ? 'delete-variant' : ''}`}>
              <div className="modal-header">
                <span className="modal-icon">{modal.action === 'delete' ? '!' : modal.user.isActive ? '!' : '+'}</span>
                <h3>{modal.action === 'delete' ? 'Permanent Off-boarding' : 'Security Confirmation'}</h3>
              </div>
              {modal.action === 'delete' ? (
                <>
                  <p>
                    Permanently remove <strong>{modal.user.name}</strong> from FlowGuard? Login access and Face ID enrolment will be permanently removed.
                  </p>
                  <p className="delete-warning-copy">
                    Attendance records will be deleted, linked security logs will remain anonymised, and operational bookings will be safely unlinked where applicable.
                  </p>
                  <label className="confirm-name-field">
                    Type the user's full name to confirm
                    <input value={confirmText} onChange={(e) => setConfirmText(e.target.value)} placeholder={modal.user.name} />
                  </label>
                </>
              ) : (
                <p>
                  Are you sure you want to <strong>{modal.user.isActive ? 'Suspend' : 'Reactivate'}</strong> access for <strong>{modal.user.name}</strong>?
                </p>
              )}
              {modalError && <div className="modal-error" role="alert">{modalError}</div>}
              <div className="modal-actions">
                <button className="cancel-btn" onClick={closeModal}>Cancel</button>
                <button
                  className={`confirm-btn ${modal.action === 'delete' ? 'delete-btn' : modal.user.isActive ? 'suspend-btn' : 'reactivate-btn'}`}
                  onClick={handleConfirmAction}
                  disabled={modal.action === 'delete' && confirmText !== modal.user.name}
                >
                  {modal.action === 'delete' ? 'Permanently Delete' : `Confirm ${modal.user.isActive ? 'Suspension' : 'Reactivation'}`}
                </button>
              </div>
            </div>
          </div>
        )}

        {addOpen && (
          <div className="modal-overlay" onClick={closeAdd}>
            <div className="modal-content" onClick={(e) => e.stopPropagation()}>
              <div className="modal-header">
                <span className="modal-icon">+</span>
                <h3>Add Tenant Account</h3>
              </div>
              {addError && <div className="add-user-error">{addError}</div>}
              <form className="add-user-form" onSubmit={createTenant}>
                <div>
                  <label>Full Name</label>
                  <input name="name" value={newUser.name} onChange={onNewField} placeholder="e.g., Jane Tan" required />
                </div>
                <div>
                  <label>Email</label>
                  <input name="email" type="email" value={newUser.email} onChange={onNewField} placeholder="name@company.com" required />
                </div>
                <div>
                  <label>Temporary Password</label>
                  <PasswordInput variant="dark" name="password" value={newUser.password} onChange={onNewField} placeholder="min 8 characters" required />
                </div>
                <div className="modal-actions">
                  <button type="button" className="cancel-btn" onClick={closeAdd}>Cancel</button>
                  <button type="submit" className="add-user-btn" disabled={addSubmitting}>
                    {addSubmitting ? 'Creating...' : 'Create Tenant'}
                  </button>
                </div>
              </form>
            </div>
          </div>
        )}

        {notification && <div className="users-toast">{notification}</div>}

        <div className="users-container">
          <header className="dashboard-header users-header">
            <div className="header-titles">
              <h1>User Management</h1>
              <p>Manage user accounts, roles, Face ID enrolment and access status.</p>
            </div>
            {role === 'FM' && <button className="add-user-btn" onClick={openAdd}>+ Add Tenant</button>}
          </header>

          <section className="user-summary-grid" aria-label="User summary">
            <div><span>Total Users</span><strong>{summary.total}</strong></div>
            <div><span>Active</span><strong>{summary.active}</strong></div>
            <div><span>Suspended</span><strong>{summary.suspended}</strong></div>
            <div><span>Face ID Enrolled</span><strong>{summary.enrolled}</strong></div>
          </section>

          <section className="user-filter-bar" aria-label="User filters">
            <input name="query" value={filters.query} onChange={onFilterChange} placeholder="Search name or email" aria-label="Search by name or email" />
            <select name="role" value={filters.role} onChange={onFilterChange} aria-label="Filter by role">
              <option>All</option><option>FM</option><option>Tenant</option><option>Staff</option>
            </select>
            <select name="status" value={filters.status} onChange={onFilterChange} aria-label="Filter by status">
              <option>All</option><option>Active</option><option>Suspended</option>
            </select>
            <select name="faceId" value={filters.faceId} onChange={onFilterChange} aria-label="Filter by Face ID">
              <option>All</option><option>Enrolled</option><option>Not Enrolled</option>
            </select>
          </section>

          <div className="table-wrapper">
            {loading ? (
              <p style={{ padding: '40px', color: '#94a3b8', textAlign: 'center' }}>Syncing with FlowGuard Database...</p>
            ) : (
              <table className="users-table">
                <thead>
                  <tr>
                    <th>Personnel</th>
                    <th>Role</th>
                    <th>Email</th>
                    <th>Status</th>
                    <th>Face ID</th>
                    <th>Joined</th>
                    <th>Actions</th>
                  </tr>
                </thead>
                <tbody>
                  {filteredUsers.length === 0 ? (
                    <tr><td colSpan="7" style={{ textAlign: 'center', padding: '40px', color: '#64748b' }}>No users match the current filters.</td></tr>
                  ) : filteredUsers.map((u) => {
                    const isSelf = String(u.id) === String(currentUserId);
                    return (
                      <tr key={u.id} className={u.isActive === false ? 'row-suspended' : ''}>
                        <td className="user-name-cell" data-label="Personnel">
                          <div className="user-identity">
                            <div className="user-avatar-small">{u.name?.charAt(0).toUpperCase()}</div>
                            <span className="user-name-text">{u.name} {isSelf && <span className="self-tag">(You)</span>}</span>
                          </div>
                        </td>
                        <td data-label="Role">{renderRoleBadge(u.role)}</td>
                        <td className="access-cell" data-label="Email">{u.email}</td>
                        <td data-label="Status">{renderStatusBadge(u)}</td>
                        <td data-label="Face ID">
                          <span className={`presence-tag ${u.isEnrolled ? 'on-site' : 'off-site'}`} title={u.isEnrolled ? 'A protected biometric template is enrolled' : 'No Face ID enrolled yet'}>
                            {u.isEnrolled ? '\u2705 Enrolled' : '\u274C Not Enrolled'}
                          </span>
                        </td>
                        <td className="time-cell" data-label="Joined">{new Date(u.createdAt).toLocaleDateString('en-SG')}</td>
                        <td className="actions-cell" data-label="Actions">
                          <div className="action-button-group" aria-label={`Actions for ${u.name}`}>
                            <button className="action-btn action-neutral" onClick={() => navigate(`/user-logs/${u.id}`)}>View Logs</button>
                            {role === 'FM' && (
                              <button className="action-btn action-neutral" onClick={() => navigate(`/enrollment?userId=${u.id}&name=${encodeURIComponent(u.name)}&returnTo=/users`)}>
                                {u.isEnrolled ? 'Re-enrol Face ID' : 'Enrol Face ID'}
                              </button>
                            )}
                            <button className={`action-btn ${u.isActive === false ? 'action-restore' : 'action-warning'} ${isSelf ? 'disabled-action' : ''}`} onClick={() => !isSelf && openModal(u, 'suspend')} disabled={isSelf}>
                              {u.isActive === false ? 'Reactivate' : 'Suspend'}
                            </button>
                            <button className={`action-btn action-danger ${isSelf ? 'disabled-action' : ''}`} onClick={() => !isSelf && openModal(u, 'delete')} disabled={isSelf}>
                              Permanent Delete
                            </button>
                          </div>
                        </td>
                      </tr>
                    );
                  })}
                </tbody>
              </table>
            )}
          </div>
        </div>
      </main>
    </div>
  );
};

export default Users;

// Backend API base URL.
// - Local dev: leave VITE_API_BASE_URL unset — relative "/api" URLs go through
//   the Vite proxy to the local Node server.
// - Vercel/production: set VITE_API_BASE_URL to the deployed Node backend
//   (e.g. https://flowguard-api.onrender.com). The Vite proxy does not exist in
//   a production build, so this must be configured for deployment.
// The frontend NEVER calls the FastAPI AI service directly — all facial
// recognition traffic goes through the Node backend.
export const API_BASE_URL = import.meta.env.VITE_API_BASE_URL || '';

import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import axios from 'axios';
import Sidebar from '../components/Sidebar';
import '../css/Dashboard.css';
import '../css/Settings.css';
import { API_BASE_URL } from '../constants/api';

const Settings = () => {
  const navigate = useNavigate();
  const [alertsEnabled, setAlertsEnabled] = useState(true);
  const [autoRecord, setAutoRecord] = useState(true);
  const [ppeStrictness, setPpeStrictness] = useState(85);
  const currentUserId = localStorage.getItem("userId");
  const currentUserName = localStorage.getItem("userName");
  const role = localStorage.getItem("userRole");
  const isFM = role === 'FM';

  // Change Password (all authenticated users)
  const [currentPassword, setCurrentPassword] = useState('');
  const [newPassword, setNewPassword] = useState('');
  const [confirmPassword, setConfirmPassword] = useState('');
  const [passwordMessage, setPasswordMessage] = useState(null); // { type: 'error'|'success', text }
  const [changingPassword, setChangingPassword] = useState(false);

  const handleSelfReEnroll = () => {
    const params = new URLSearchParams({
      userId: currentUserId,
      name: currentUserName || 'My profile',
      returnTo: '/settings'
    });
    navigate(`/enrollment?${params.toString()}`);
  };

  const handleChangePassword = async (e) => {
    e.preventDefault();
    setPasswordMessage(null);

    if (!currentPassword || !newPassword || !confirmPassword) {
      setPasswordMessage({ type: 'error', text: 'All three password fields are required.' });
      return;
    }
    if (newPassword.length < 8) {
      setPasswordMessage({ type: 'error', text: 'New password must be at least 8 characters.' });
      return;
    }
    if (newPassword === currentPassword) {
      setPasswordMessage({ type: 'error', text: 'New password must be different from the current password.' });
      return;
    }
    if (newPassword !== confirmPassword) {
      setPasswordMessage({ type: 'error', text: 'New password and confirmation do not match.' });
      return;
    }

    setChangingPassword(true);
    try {
      const token = localStorage.getItem('accessToken');
      await axios.put(`${API_BASE_URL}/user/change-password`, {
        currentPassword,
        newPassword
      }, {
        headers: { Authorization: `Bearer ${token}` }
      });

      // The backend revoked every existing session (tokenVersion bump), so the
      // current token is dead too — clear the session and require a fresh login.
      setPasswordMessage({ type: 'success', text: 'Password changed. Redirecting to login…' });
      localStorage.clear();
      navigate('/login', { state: { notice: 'Password changed successfully. Please log in with your new password.' } });
    } catch (err) {
      const text = err.response?.data?.message || 'Password change failed. Please try again.';
      setPasswordMessage({ type: 'error', text });
    } finally {
      setChangingPassword(false);
    }
  };

  return (
    <div className="dashboard-layout">
      {/* 2. Replace the entire <aside> block with this one line */}
      <Sidebar />

      {/* --- MAIN SETTINGS CONTENT --- */}
      <main className="dashboard-main">
        <header className="dashboard-header settings-header">
          <div className="header-titles">
            <h1>{isFM ? 'System Configuration' : 'Settings'}</h1>
            <p>
              {isFM
                ? 'Manage AI thresholds, camera networks, and alert routing'
                : 'Manage your personal biometric profile and access settings.'}
            </p>
          </div>
        </header>

        <div className="settings-grid">

          {/* --- FM-only system administration --- */}
          {isFM && (
            <>
          {/* AI Configuration Card */}
          <section className="settings-card">
            <div className="card-header">
              <h3>🧠 FlowGuard AI Engine</h3>
              <p>Adjust the machine learning detection parameters.</p>
            </div>

            <div className="setting-row">
              <div className="setting-info">
                <h4>PPE Detection Strictness</h4>
                <p>Minimum confidence required to flag an anomaly.</p>
              </div>
              <div className="setting-control slider-control">
                <span className="slider-value">{ppeStrictness}%</span>
                <input 
                  type="range" min="50" max="99" 
                  value={ppeStrictness} 
                  onChange={(e) => setPpeStrictness(e.target.value)} 
                />
              </div>
            </div>

            <div className="setting-row">
              <div className="setting-info">
                <h4>Auto-Record on Incident</h4>
                <p>Save 30 seconds of footage before and after a triggered alert.</p>
              </div>
              <div className="setting-control">
                <label className="toggle-switch">
                  <input type="checkbox" checked={autoRecord} onChange={() => setAutoRecord(!autoRecord)} />
                  <span className="toggle-slider"></span>
                </label>
              </div>
            </div>
          </section>

          {/* Network & Alerts Card */}
          <section className="settings-card">
            <div className="card-header">
              <h3>📡 Network & Notifications</h3>
              <p>Manage how FlowGuard communicates with the floor managers.</p>
            </div>

            <div className="setting-row">
              <div className="setting-info">
                <h4>Push Notifications to Mobile</h4>
                <p>Instantly alert floor supervisors of hygiene violations.</p>
              </div>
              <div className="setting-control">
                <label className="toggle-switch">
                  <input type="checkbox" checked={alertsEnabled} onChange={() => setAlertsEnabled(!alertsEnabled)} />
                  <span className="toggle-slider"></span>
                </label>
              </div>
            </div>

            <div className="setting-row">
              <div className="setting-info">
                <h4>Camera Feed Quality</h4>
                <p>Lower quality saves bandwidth but reduces AI accuracy.</p>
              </div>
              <div className="setting-control">
                <select className="dark-select">
                  <option>1080p (Standard)</option>
                  <option>4K (High AI Accuracy)</option>
                  <option>720p (Bandwidth Saver)</option>
                </select>
              </div>
            </div>
          </section>
            </>
          )}

          {/* --- Biometric Profile: available to ALL authenticated users --- */}
          <section className="settings-card">
            <div className="card-header">
              <h3>Biometric Profile</h3>
              <p>Refresh your Face ID if gate recognition becomes unreliable.</p>
            </div>
            <div className="setting-row">
              <div className="setting-info">
                <h4>Face ID Re-enrollment</h4>
                <p>Use either camera capture or manual photo upload to replace your current facial vector.</p>
              </div>
              <div className="setting-control">
                <button className="save-btn" onClick={handleSelfReEnroll}>Re-enroll My Face ID</button>
              </div>
            </div>
          </section>

          {/* --- Account Security: available to ALL authenticated users --- */}
          <section className="settings-card">
            <div className="card-header">
              <h3>🔐 Account Security</h3>
              <p>Change your FlowGuard sign-in password. You will be logged out of all devices.</p>
            </div>
            <form onSubmit={handleChangePassword}>
              <div className="setting-row">
                <div className="setting-info">
                  <h4>Current Password</h4>
                </div>
                <div className="setting-control">
                  <input
                    type="password"
                    className="dark-select"
                    autoComplete="current-password"
                    value={currentPassword}
                    onChange={(e) => setCurrentPassword(e.target.value)}
                    placeholder="Current password"
                    aria-label="Current Password"
                  />
                </div>
              </div>
              <div className="setting-row">
                <div className="setting-info">
                  <h4>New Password</h4>
                  <p>Minimum 8 characters, different from your current password.</p>
                </div>
                <div className="setting-control">
                  <input
                    type="password"
                    className="dark-select"
                    autoComplete="new-password"
                    value={newPassword}
                    onChange={(e) => setNewPassword(e.target.value)}
                    placeholder="New password"
                    aria-label="New Password"
                  />
                </div>
              </div>
              <div className="setting-row">
                <div className="setting-info">
                  <h4>Confirm New Password</h4>
                </div>
                <div className="setting-control">
                  <input
                    type="password"
                    className="dark-select"
                    autoComplete="new-password"
                    value={confirmPassword}
                    onChange={(e) => setConfirmPassword(e.target.value)}
                    placeholder="Repeat new password"
                    aria-label="Confirm New Password"
                  />
                </div>
              </div>
              {passwordMessage && (
                <p
                  role="alert"
                  style={{ color: passwordMessage.type === 'error' ? '#f87171' : '#34d399', padding: '0 4px' }}
                >
                  {passwordMessage.text}
                </p>
              )}
              <div className="setting-row">
                <div className="setting-info" />
                <div className="setting-control">
                  <button type="submit" className="save-btn" disabled={changingPassword}>
                    {changingPassword ? 'Changing…' : 'Change Password'}
                  </button>
                </div>
              </div>
            </form>
          </section>

          {/* --- FM-only: Danger Zone + system save --- */}
          {isFM && (
            <>
          {/* Danger Zone Card */}
          <section className="settings-card danger-zone">
            <div className="card-header">
              <h3 className="text-red">⚠️ Danger Zone</h3>
            </div>
            <div className="setting-row">
              <div className="setting-info">
                <h4>Reboot Network Nodes</h4>
                <p>Force restart all 128 active CCTV cameras. Expect 3 minutes of downtime.</p>
              </div>
              <div className="setting-control">
                <button className="danger-btn">Initiate Reboot</button>
              </div>
            </div>
          </section>

          <div className="settings-actions">
            <button className="save-btn">Save Changes</button>
          </div>
            </>
          )}

        </div>
      </main>
    </div>
  );
};

export default Settings;

