76	  const [systemTime, setSystemTime] = useState(new Date().toLocaleTimeString('en-SG', { 
77	    hour: '2-digit', minute: '2-digit', second: '2-digit', hour12: true 
78	  }));
79	
80	  const [incidentLogs, setIncidentLogs] = useState([]);
81	
