86	
87	  const token = localStorage.getItem("accessToken");
88	  // All recognition traffic goes through the Node backend â€” never FastAPI directly.
89	  const NODE_SERVER_URL = `${API_BASE_URL}/api/security/logs`;
90	  const RECOGNIZE_URL = `${API_BASE_URL}/api/facial-recognition/recognize`;
91	  // V-Patrol is a monitoring post: it records access AUDIT events only and must
