150	    };
151	  }, []);
152	
153	  const applyCameraSource = (source, statusMsg) => {
154	    cameraSourceRef.current = source;
155	    setCameraSource(source);
156	    setCameraStatusMsg(statusMsg);
157	    piFailStreakRef.current = 0;
158	  };
159	
160	  // Primary source: Raspberry Pi Gate Camera. Probe the snapshot endpoint on
161	  // load; if unreachable, automatically fall back to the laptop webcam.
162	  const initCameraSource = async () => {
163	    const piReachable = await isPiCameraReachable();
164	    if (piReachable) {
165	      stopCCTV();
166	      applyCameraSource(CAMERA_SOURCES.PI, CAMERA_STATUS_MESSAGES.PI_CONNECTED);
167	      changeScanState("SYSTEM_ACTIVE");
