169	      applyCameraSource(CAMERA_SOURCES.WEBCAM, CAMERA_STATUS_MESSAGES.PI_UNAVAILABLE);
170	      await startCCTV();
171	    }
172	  };
173	
174	  // Manual camera source switch (Pi Gate Camera / Laptop Webcam)
175	  const selectCameraSource = async (source) => {
176	    if (source === cameraSourceRef.current) return;
177	    if (source === CAMERA_SOURCES.PI) {
178	      const piReachable = await isPiCameraReachable();
179	      if (piReachable) {
180	        stopCCTV();
181	        applyCameraSource(CAMERA_SOURCES.PI, CAMERA_STATUS_MESSAGES.PI_CONNECTED);
182	        changeScanState("SYSTEM_ACTIVE");
183	      } else {
184	        applyCameraSource(CAMERA_SOURCES.WEBCAM, CAMERA_STATUS_MESSAGES.PI_UNAVAILABLE);
