281	    const canvas = canvasRef.current;
282	    if (!canvas) return null;
283	    const context = canvas.getContext('2d');
284	    const MAX_WIDTH = CAPTURE_MAX_WIDTH;
285	
286	    if (cameraSourceRef.current === CAMERA_SOURCES.PI) {
287	      let bitmap;
288	      try {
