297	        }
298	        return null;
299	      }
300	      const scale = Math.min(1, MAX_WIDTH / bitmap.width);
301	      canvas.width = Math.round(bitmap.width * scale);
302	      canvas.height = Math.round(bitmap.height * scale);
303	      context.drawImage(bitmap, 0, 0, canvas.width, canvas.height);
304	      bitmap.close?.();
305	      return canvas.toDataURL('image/jpeg', 0.3);
306	    }
307	
308	    const video = videoRef.current;
