324	    if (scanStatusRef.current === "SECURE_MATCH" || scanStatusRef.current === "UNKNOWN_QUERY") return;
325	
326	    gate.begin();
327	    const totalTimer = startTimer();
328	
329	    try {
330	      const captureTimer = startTimer();
331	      const imageBase64 = await captureFrameBase64();
332	      const captureMs = captureTimer();
333	      if (!imageBase64) return;
334	
335	      const apiTimer = startTimer();
336	      const res = await axios.post(RECOGNIZE_URL,
337	        { image: imageBase64, cameraLocation: CAMERA_LOCATION },
338	        { headers: { Authorization: `Bearer ${token}` } }
339	      );
340	      logScanTimings({
341	        captureMs,
342	        apiMs: apiTimer(),
343	        totalMs: totalTimer(),
344	        serverTimings: res.data?.timings
345	      });
346	      setServiceNotice('');
347	
348	      if (scanStatusRef.current === "SECURE_MATCH" || scanStatusRef.current === "UNKNOWN_QUERY") {
349	         return;
350	      }
351	
352	      if (res.data && Array.isArray(res.data.box) && res.data.box.length === 4) {
353	        // FastAPI contract: box is exactly [x, y, width, height] in pixels of
354	        // the captured frame. Direct mapping (no corner-order guessing),
355	        // clamped to the frame, projected onto the contain-fit preview.
356	        const frame = { width: canvas.width, height: canvas.height };
