361	        const { width: boxWidth } = clampBoxToFrame(res.data.box, frame.width, frame.height);
362	        const targetBox = faceBoxStyle(res.data.box, frame, container, 'contain');
363	
364	        // Calculate proximity based on the compressed canvas width
365	        const faceProximityPercentage = (boxWidth / canvas.width) * 100;
366	        const livenessRatio = res.data.liveness_ratio || 0.5;
367	
368	        if (faceProximityPercentage < 5 && scanStatusRef.current !== "LIVENESS_CHECK") {
369	          if (scanStatusRef.current === "SYSTEM_ACTIVE" || scanStatusRef.current === "PRESENCE_DETECTED") {
