386	        if (scanStatusRef.current === "SYSTEM_ACTIVE" || scanStatusRef.current === "PRESENCE_DETECTED") {
387	          changeScanState("TARGET_LOCKING");
388	          setFaceBox(targetBox);
389	          setScanProgress(12);
