396	              clearInterval(progressIntervalRef.current);
397	            } else {
398	              setScanProgress(progress);
399	            }
400	          }, 120);
401	
402	          lockTimerRef.current = setTimeout(() => {
403	            clearInterval(progressIntervalRef.current);
404	            
405	            const currentTimestamp = Date.now();
406	            const logTimeStr = new Date().toLocaleTimeString('en-SG', { hour: '2-digit', minute: '2-digit', second: '2-digit', hour12: true });
407	
408	            const recognizedUser = res.data.user;
409	            if (recognizedUser && recognizedUser.status === RECOGNITION_STATUS.AUTHORIZED) {
410	              candidateUserRef.current = { ...recognizedUser, _evaluationResult: res.data };
411	              changeScanState("LIVENESS_CHECK");
412	            } else {
413	              // Suspended or unknown â€” the Node backend has already written the
414	              // deduplicated SecurityLog; the client only updates its local timeline.
415	              const isSuspended = recognizedUser && recognizedUser.status === RECOGNITION_STATUS.SUSPENDED;
416	              const subject = describeRecognitionSubject(recognizedUser);
417	
418	              playFeedback('denied');
419	              changeScanState("UNKNOWN_QUERY");
420	              setIdentifiedUser(isSuspended ? `${subject.identityLabel} â€” SUSPENDED` : "UNKNOWN PERSONNEL");
421	              setScanProgress(0);
422	              setLastEvaluationDecision({ identityLabel: isSuspended ? subject.identityLabel : 'Unknown', accessLabel: 'Access Denied', action: 'Security log created', result: res.data, message: '' });
423	
424	              const dedupName = isSuspended ? recognizedUser.name : "UNKNOWN";
425	              if (lastLogRef.current.name !== dedupName || (currentTimestamp - lastLogRef.current.timestamp > 10000)) {
426	                const newLog = {
427	                  id: `SEC-${Date.now()}`,
428	                  // New event happening right now â€” stamped at detection time.
429	                  occurredAt: new Date(currentTimestamp).toISOString(),
430	                  time: logTimeStr,
431	                  type: isSuspended ? 'Suspended Access Attempt' : 'Intrusion Alert',
432	                  desc: isSuspended
433	                    ? `Suspended account denied at gantry: ${subject.identityLabel}.`
434	                    : 'Unregistered personnel detected at gantry.',
435	                  severity: 'critical',
436	                  icon: isSuspended ? 'â›”' : 'ðŸš¨',
437	                  personnelName: isSuspended ? recognizedUser.name : null,
438	                  role: isSuspended ? recognizedUser.role : null,
439	                  confidence: recognizedUser ? recognizedUser.confidence : null,
440	                  cameraLocation: CAMERA_LOCATION
441	                };
442	
443	                setIncidentLogs(prev => [newLog, ...prev.slice(0, 14)]);
444	                lastLogRef.current = { name: dedupName, timestamp: currentTimestamp };
445	              }
446	
447	              setTimeout(() => { resetScanner(); }, 3500);
448	            }
449	          }, TARGET_LOCK_MS);
450	
451	        } else if (scanStatusRef.current === "TARGET_LOCKING") {
452	          setFaceBox(targetBox);
453	        }
454	
455	      } else {
