457	          setLastEvaluationDecision({ identityLabel: 'No Face', accessLabel: 'No Decision', action: 'No suspicious log created', result: { ...res.data, detectionOutcome: DETECTION_OUTCOMES.NO_FACE }, message: '' });
458	          resetScanner();
459	        }
460	      }
461	    } catch (err) {
462	      // Node/FastAPI unavailable â€” back off instead of flooding the endpoint.
463	      // The camera preview keeps running; webcam fallback is ONLY for Pi failure.
464	      console.error("AI Command Loop Fault:", err);
465	      scanGateRef.current.applyBackoff();
