6	import '../css/FacialEvaluation.css';
7	import { API_BASE_URL } from '../constants/api';
8	import { CAMERA_SOURCES, CAMERA_STATUS_MESSAGES, isPiCameraReachable, fetchPiSnapshotBitmap } from '../constants/piCamera';
9	import {
10	  SCENARIOS,
11	  ENROLLED_LABELS,
12	  IDENTITY_LABELS,
13	  NO_FACE,
14	  UNKNOWN_LABEL,
15	  CONDITIONS,
16	  SOURCES,
