file.content:
.users-header {
    align-items: center;
}

.user-summary-grid {
    display: grid;
    grid-template-columns: repeat(4, minmax(140px, 1fr));
    gap: 12px;
    margin-bottom: 14px;
}

.user-summary-grid > div {
    background: #1e293b;
    border: 1px solid #334155;
    border-radius: 8px;
    padding: 14px 16px;
}

.user-summary-grid span {
    display: block;
    color: #94a3b8;
    font-size: 0.76rem;
    font-weight: 800;
    text-transform: uppercase;
    letter-spacing: 0.04em;
}

.user-summary-grid strong {
    display: block;
    margin-top: 6px;
    color: #f8fafc;
    font-size: 1.55rem;
}

.user-filter-bar {
    display: grid;
    grid-template-columns: minmax(220px, 2fr) repeat(3, minmax(140px, 1fr));
    gap: 10px;
    margin-bottom: 14px;
}

.user-filter-bar input,
.user-filter-bar select,
.confirm-name-field input {
    width: 100%;
    background: #0f172a;
    border: 1px solid #334155;
    color: #f8fafc;
    border-radius: 8px;
    padding: 10px 12px;
    font: inherit;
}

.user-filter-bar input:focus,
.user-filter-bar select:focus,
.confirm-name-field input:focus {
    outline: none;
    border-color: #3b82f6;
    box-shadow: 0 0 0 3px rgba(59, 130, 246, 0.15);
}

.account-status-badge {
    display: inline-flex;
    align-items: center;
    border-radius: 8px;
    padding: 6px 12px;
    font-size: 0.8rem;
    font-weight: 800;
    border: 1px solid transparent;
}

.account-status-badge.active {
    color: #34d399;
    background: rgba(16, 185, 129, 0.1);
    border-color: rgba(16, 185, 129, 0.25);
}

.account-status-badge.suspended {
    color: #fb7185;
    background: rgba(244, 63, 94, 0.1);
    border-color: rgba(244, 63, 94, 0.25);
}

.delete-warning-copy {
    background: rgba(244, 63, 94, 0.08);
    border: 1px solid rgba(244, 63, 94, 0.18);
    border-radius: 8px;
    padding: 12px;
    font-size: 0.88rem;
}

.confirm-name-field {
    display: block;
    color: #cbd5e1;
    font-size: 0.86rem;
    font-weight: 700;
    text-align: left;
    margin: 12px 0;
}

.confirm-name-field input {
    margin-top: 8px;
}

.modal-error {
    background: rgba(244, 63, 94, 0.12);
    border: 1px solid rgba(244, 63, 94, 0.28);
    color: #fecdd3;
    border-radius: 8px;
    padding: 10px 12px;
    margin-bottom: 14px;
    font-weight: 700;
}

.confirm-btn:disabled {
    opacity: 0.45;
    cursor: not-allowed;
    transform: none !important;
}
