    display: flex;
    justify-content: flex-end;
    gap: 10px;
}

.eval-recorder-cancel {
    background: #334155;
    color: #cbd5e1;
    border: none;
    border-radius: 8px;
    padding: 10px 18px;
    font-weight: 700;
    cursor: pointer;
}

.eval-recorder-cancel:hover {
    background: #475569;
}

.eval-recorder-save {
    background: #1d4ed8;
    color: white;
    border: 1px solid #3b82f6;
    border-radius: 8px;
    padding: 10px 18px;
    font-weight: 700;
    cursor: pointer;
}

.eval-recorder-save:hover {
    background: #2563eb;
}

.eval-recorder-save:disabled {
    opacity: 0.45;
    cursor: not-allowed;
}

