// Backend tests — Smart Logistics booking CRUD + WhatsApp (disabled/mock-safe).
const express = require("express");
const request = require("supertest");
const jwt = require("jsonwebtoken");

const mockBooking = {
  create: jest.fn(),
  findAll: jest.fn(),
  findByPk: jest.fn(),
  findOne: jest.fn(),
};
const mockUser = { findByPk: jest.fn() };

jest.mock("../../models", () => ({ Booking: mockBooking, User: mockUser }));

// Ensure WhatsApp runs in disabled/simulated mode (no real sends, no crash).
delete process.env.WHATSAPP_ENABLED;
process.env.APP_SECRET = "test-secret";

const bookingRouter = require("../../routes/booking");
const whatsapp = require("../../services/whatsappService");

const app = express();
app.use(express.json());
app.use("/api/bookings", bookingRouter);

// verifyToken is now DB-backed: it re-reads the account via User.findByPk and
// the DB role is authoritative. Each role therefore needs its own id, and the
// mocked User table below is keyed by those ids. Tenant keeps id 7 so the
// tenantId-scoping assertions (tenantId: 7) remain unchanged.
const ID_BY_ROLE = { FM: 1, Staff: 9, Tenant: 7 };
const DB_USERS = {
  1: { id: 1, role: "FM", isActive: true },
  7: { id: 7, role: "Tenant", isActive: true },
  // managerId feeds resolveTenantId for Staff-created bookings (route-level findByPk).
  9: { id: 9, role: "Staff", isActive: true, managerId: 50 },
};
const mockDbUsers = () =>
  mockUser.findByPk.mockImplementation((id) => Promise.resolve(DB_USERS[id] || null));

const tokenFor = (role) => jwt.sign({ id: ID_BY_ROLE[role], role, email: `${role}@harrison.com` }, process.env.APP_SECRET);

const validBody = {
  transport_company: "NinjaVan",
  license_plate: "GBG 1234M",
  driver_phone: "+6591234567",
  loading_bay: "Bay A",
};

describe("Booking routes", () => {
  beforeEach(() => {
    jest.clearAllMocks();
    mockDbUsers(); // re-arm the DB-backed auth lookup after clearing mocks
  });

  test("POST /create rejects missing required fields (400)", async () => {
    const res = await request(app)
      .post("/api/bookings/create")
      .set("Authorization", `Bearer ${tokenFor("FM")}`)
      .send({ transport_company: "NinjaVan" });
    expect(res.status).toBe(400);
  });

  test("POST /create creates a Pending booking (201)", async () => {
    mockBooking.create.mockResolvedValue({ id: 1, ...validBody, status: "Pending" });
    const res = await request(app)
      .post("/api/bookings/create")
      .set("Authorization", `Bearer ${tokenFor("FM")}`)
      .send(validBody);
    expect(res.status).toBe(201);
    expect(mockBooking.create).toHaveBeenCalledWith(expect.objectContaining({ status: "Pending" }));
  });

  test("POST /create triggers a (simulated) WhatsApp confirmation", async () => {
    mockBooking.create.mockResolvedValue({ id: 1, ...validBody, booking_ref: "FG-AAA", status: "Pending" });
    const res = await request(app)
      .post("/api/bookings/create")
      .set("Authorization", `Bearer ${tokenFor("FM")}`)
      .send(validBody);
    expect(res.status).toBe(201);

